import{_ as l,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017-MAR-01 -- Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAR-01 -- Ceph Performance Weekly","date":"2017-03-15T00:00:00.000Z","updated":"2017-03-15T00:00:00.000Z","tags":["Ceph","性能测试","代码审查","分布式存储","Blue Store"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAR-01_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAR-01_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),i={name:"posts/2017/2017-MAR-01_-_-_Ceph_Performance_Weekly.md"};function s(p,e,a,n,_,u){return t(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： 会议主持人、研发人员、测试人员等</p><p><strong>会议内容</strong>：</p><p><strong>一、主要议题</strong></p><ol><li><p><strong>代码审查与Pull Request</strong></p><ul><li>研发人员介绍了近期对代码库的拆分、修复Hanoi的bug、处理来自Narratives团队的Pull Request等工作进展。</li><li>讨论了使用Wheless内存和清理代码的建议，以及与Boyd关于使用RAM作为日志存储的测试。</li><li>提出对低优先级补丁进行初步审查，但不必深入。</li></ul></li><li><p><strong>测试与性能</strong></p><ul><li>进行了简单的覆盖测试，并对Blue Store进行了测试，结果显示Boost在EC和RVD文件存储方面表现可接受。</li><li>讨论了测试中需关注的性能问题，如缓存缺失和位图分配器阻塞。</li></ul></li><li><p><strong>其他</strong></p><ul><li>讨论了测试GIF文件的问题和硬件设备的准备情况。</li><li>讨论了性能测试的建议，包括对锁定PR和位图分配器提示的测试。</li></ul></li></ol><p><strong>二、决定事项</strong></p><ol><li>对Pull Request进行初步审查，并重点关注性能问题。</li><li>对位图分配器阻塞进行测试。</li><li>准备硬件设备，进行实际测试。</li><li>对锁定PR和位图分配器提示进行性能测试。</li></ol><p><strong>三、后续行动计划</strong></p><ol><li>研发人员继续进行代码审查和Pull Request处理。</li><li>测试人员负责进行性能测试和位图分配器阻塞测试。</li><li>准备硬件设备，进行实际测试。</li><li>对锁定PR和位图分配器提示进行性能测试。</li></ol><p><strong>四、会议总结</strong></p><p>本次会议主要讨论了代码审查、测试和性能等方面的问题，明确了后续行动计划，并要求相关人员按照计划推进工作。会议内容涵盖了Ceph的代码审查、性能测试、硬件准备等关键议题，确保了Ceph项目的持续优化和改进。</p>',12)])])}const d=l(i,[["render",s]]);export{c as __pageData,d as default};
